/// This is the Data Contract class for the SalesOrderLoadPlanning SSRS Report
/// The METSalesOrderLoadPlanningContract class is the data contract class for the SalesOrderLoadPlanning
/// SSRS report.
/// </summary>

[
    DataContractAttribute
]
class METSalesOrderLoadPlanningContract
{
    SalesShippingDateConfirmed  confirmedShipDateFrom;
    SalesShippingDateRequested  confirmedShipDateTo;



}

