/// </param>
/// <returns>
/// The current value of datacontract parameter.
/// </returns>
[DataMember('ConfirmedShipDateFrom')
 ,SysOperationLabelAttribute(literalstr("@MET:ConfirmShipDateFrom"))]
public SalesShippingDateConfirmed parmConfirmedShipDateFrom(SalesShippingDateConfirmed _confirmedShipDateFrom = confirmedShipDateFrom)
{
    confirmedShipDateFrom = _confirmedShipDateFrom;

    return confirmedShipDateFrom;
}

